$ErrorActionPreference='Stop'
$root=Join-Path $PSScriptRoot '../docs/evidence/v131-formal-20261025'
$rows=@(Get-Content (Join-Path $root 'completed/task.jsonl')|ForEach-Object {$_|ConvertFrom-Json})
$state=Get-Content (Join-Path $root 'final-state.json') -Raw|ConvertFrom-Json
$after=(Get-Content (Join-Path $root 'output-final-raw.json') -Raw|ConvertFrom-Json)[0]
$first=(Get-Content (Join-Path $root 'output-first-raw.json') -Raw|ConvertFrom-Json)[0]
$open=$rows|Where-Object event -eq 'OPEN AbstractContainerMenu BlockPos{x=1066, y=57, z=23}'|Select-Object -First 1
$before=$rows|Where-Object {$_.time -gt $open.time -and $_.menu.Count -eq 63}|Select-Object -First 1
function Same($a,$b){[System.Text.Json.Nodes.JsonNode]::DeepEquals([System.Text.Json.Nodes.JsonNode]::Parse((ConvertTo-Json -InputObject $a -Depth 100 -Compress)),[System.Text.Json.Nodes.JsonNode]::Parse((ConvertTo-Json -InputObject $b -Depth 100 -Compress)))}
$boxes=@($after.items|Where-Object item -eq 'minecraft:light_blue_shulker_box')
$originalSlots=foreach($i in 0..26){if($i -in $boxes.slot){continue};[ordered]@{slot=$i;unchanged=(Same $before.menu[$i] ($after.items|Where-Object slot -eq $i).serialized)}}
$levels=0;$spent=0;$pending=$null;$buys=0;$costs=@()
foreach($r in $rows){if($r.event -match '^RESULT (?:CONFIRMED|RECONCILED AFTER MENU CLOSE) cost=(\d+)$'){$levels += [int]$Matches[1]};if($r.event -match '^TRADE BUY INTENT index=\d+ emeralds=(\d+)$'){if($null -ne $pending){throw 'Overlapping trade intent'};$pending=[int]$Matches[1]};if($r.event -like 'TRADE BUY CONFIRMED*'){if($null -eq $pending){throw 'Missing trade intent'};$spent+=$pending;$costs+=$pending;$buys++;$pending=$null}}
$target='D:/MC/PCL 正式版 2.10.6/.minecraft/versions/26.2-自动打装备'
$backup=Join-Path $PSScriptRoot '../runtime/pcl-equipment-client/backups/v130-before-v131-merchantfix-20261025'
$configs=foreach($name in @('settings.json','workshop.json')){[ordered]@{file=$name;unchanged=((Get-FileHash "$target/config/auto-equipment-making/$name").Hash -eq (Get-FileHash "$backup/config/auto-equipment-making/$name").Hash)}}
$foodEvents=@($rows|Where-Object event -match '^FOOD|EAT')
$check=[ordered]@{task=$state.task;oneTask=(@($rows.task|Select-Object -Unique).Count -eq 1);starts=@($rows|Where-Object event -eq 'START').Count;completedEvents=@($rows|Where-Object event -eq 'COMPLETED').Count;deliveredEvents=@($rows|Where-Object event -eq 'DELIVERED').Count;finalState=$state.state;queueSize=$state.queueSize;running=$state.running;uncertain=$state.uncertain;awaitingGood=$state.awaitingGood;finalCursor=$state.cursor;completedItems=[int]$state.completed;deliveredBoxes=[int]$state.deliveredKits;levelsSpent=$levels;finalLevels=$state.levels;confirmedPurchases=$buys;emeraldsSpent=$spent;confirmedTradeCosts=$costs;pendingTradeIntent=$pending;recoveryOrCancelEvents=@($rows|Where-Object {$_.state -eq 'RECOVERY_REQUIRED' -or $_.event -match 'CANCELLED|没有安全路线'}).Count;cooldownChecks=@($rows|Where-Object event -like 'TRADE COOLDOWN CHECK*').Count;cooldownRecovered=@($rows|Where-Object event -like 'NOTICE 村民补货完成*').Count;goodAcknowledgements=@($rows|Where-Object event -like 'RESTOCK ACK*').Count;boxes=@($boxes|Select-Object slot,validKit,@{N='itemCount';E={$_.contents.Count}},@{N='allFullDurability';E={@($_.contents|Where-Object damage -ne 0).Count -eq 0}},@{N='allCountOne';E={@($_.contents|Where-Object count -ne 1).Count -eq 0}});firstBoxUnchangedAfterSecondDelivery=(Same ($first.items|Where-Object slot -eq 1).serialized ($after.items|Where-Object slot -eq 1).serialized);originalOutputUnchanged=(@($originalSlots|Where-Object {!$_.unchanged}).Count -eq 0);originalSlotsCompared=@($originalSlots).Count;configurationChecks=$configs;initialFood=34;finalFood=@($state.inventory|Where-Object slot -eq 0).stack;foodEvents=$foodEvents|Select-Object time,event;finalInventory=$state.inventory;productionBasePlans=@($rows|Where-Object event -like 'BASE PLAN*'|Select-Object event);formalScope='Newcomer mode two boxes; no formal bulk-mode or multiple Unbreaking III vendor coverage';serverMSPTCollected=$false;serverTPSCollected=$false;clientStopped=$false;passed=$false}
$pass=$check.oneTask -and $check.starts -eq 1 -and $check.completedEvents -eq 1 -and $check.deliveredEvents -eq 2 -and $state.state -eq 'COMPLETED' -and $state.queueSize -eq 0 -and $state.running -eq 'false' -and $state.uncertain -eq 'false' -and $state.awaitingGood -eq 'false' -and $state.cursor -eq '0 minecraft:air' -and $check.completedItems -eq 28 -and $check.deliveredBoxes -eq 2 -and $levels -eq 570 -and $state.levels -eq 5 -and $buys -eq 40 -and $spent -eq 228 -and $null -eq $pending -and $check.recoveryOrCancelEvents -eq 0 -and $check.cooldownRecovered -eq 2 -and $check.goodAcknowledgements -eq 1 -and $boxes.Count -eq 2 -and @($check.boxes|Where-Object {!$_.validKit -or $_.itemCount -ne 14 -or !$_.allFullDurability -or !$_.allCountOne}).Count -eq 0 -and $check.firstBoxUnchangedAfterSecondDelivery -and $check.originalOutputUnchanged -and @($configs|Where-Object {!$_.unchanged}).Count -eq 0
$check.passed=$pass
$check|ConvertTo-Json -Depth 10|Set-Content (Join-Path $root 'final-checks.json') -Encoding utf8
[pscustomobject]$check|Select-Object task,passed,completedItems,deliveredBoxes,levelsSpent,confirmedPurchases,emeraldsSpent,originalOutputUnchanged,firstBoxUnchangedAfterSecondDelivery,finalFood,productionBasePlans,foodEvents|ConvertTo-Json -Depth 5
if(!$pass){throw 'Final formal verification failed'}
